PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_templates (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', purpose TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('draft','active','archived')), version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_template_fields (id TEXT PRIMARY KEY, template_id TEXT NOT NULL REFERENCES context_templates(id) ON DELETE CASCADE, field_key TEXT NOT NULL, label TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', value_type TEXT NOT NULL CHECK(value_type IN('text','long_text','boolean','single_choice','multi_choice','number','date')), required INTEGER NOT NULL CHECK(required IN(0,1)), display_order INTEGER NOT NULL, options_json TEXT NOT NULL DEFAULT '[]', sharing_default TEXT NOT NULL CHECK(sharing_default IN('always','purpose_only','private','never')), sensitivity TEXT NOT NULL CHECK(sensitivity IN('normal','sensitive','highly_sensitive')), reason TEXT NOT NULL, UNIQUE(template_id,field_key), UNIQUE(template_id,display_order)) STRICT;
CREATE TABLE IF NOT EXISTS context_entries (id TEXT PRIMARY KEY, template_id TEXT NOT NULL REFERENCES context_templates(id), template_version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN('draft','active','archived')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_values (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES context_entries(id) ON DELETE CASCADE, field_key TEXT NOT NULL, value_json TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN('user_input','metheory_import','manual_import')), source_id TEXT, user_confirmed INTEGER NOT NULL CHECK(user_confirmed IN(0,1)), sharing TEXT NOT NULL CHECK(sharing IN('always','purpose_only','private','never')), sensitivity TEXT NOT NULL CHECK(sensitivity IN('normal','sensitive','highly_sensitive')), recorded_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(entry_id,field_key)) STRICT;
CREATE TABLE IF NOT EXISTS context_profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL, target TEXT NOT NULL, detail_level TEXT NOT NULL CHECK(detail_level IN('short','standard','detailed')), maximum_characters INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_profile_fields (profile_id TEXT NOT NULL REFERENCES context_profiles(id) ON DELETE CASCADE, template_id TEXT NOT NULL, field_key TEXT NOT NULL, PRIMARY KEY(profile_id,template_id,field_key)) STRICT;
CREATE TABLE IF NOT EXISTS context_import_records (id TEXT PRIMARY KEY, source_system TEXT NOT NULL, source_candidate_id TEXT NOT NULL, source_hypothesis_id TEXT, payload_json TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN('pending','accepted','edited_and_accepted','held','rejected')), target_template_id TEXT, target_field_key TEXT, created_value_id TEXT, imported_at TEXT NOT NULL, UNIQUE(source_system,source_candidate_id)) STRICT;
CREATE TABLE IF NOT EXISTS context_conflicts (id TEXT PRIMARY KEY, field_keys_json TEXT NOT NULL, value_ids_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('unresolved','keep_latest','keep_both','resolved_manually')), created_at TEXT NOT NULL, resolved_at TEXT) STRICT;
CREATE TABLE IF NOT EXISTS context_exports (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES context_profiles(id), format TEXT NOT NULL CHECK(format IN('markdown','json','agents','chatgpt')), content TEXT NOT NULL, omitted_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS privacy_audit_logs (id TEXT PRIMARY KEY, action TEXT NOT NULL, summary_json TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE INDEX IF NOT EXISTS context_values_entry_idx ON context_values(entry_id,field_key);
CREATE INDEX IF NOT EXISTS context_import_records_decision_idx ON context_import_records(decision,imported_at);
CREATE TABLE IF NOT EXISTS context_documents (id TEXT PRIMARY KEY, file_path TEXT NOT NULL UNIQUE, title TEXT NOT NULL, recorded_at TEXT NOT NULL, source_updated_at TEXT NOT NULL, content_hash TEXT NOT NULL, file_size INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT) STRICT;
CREATE INDEX IF NOT EXISTS context_documents_recorded_at_idx ON context_documents(recorded_at DESC);
CREATE VIRTUAL TABLE IF NOT EXISTS context_document_fts USING fts5(document_id UNINDEXED,title,body);
CREATE TABLE IF NOT EXISTS context_entry_candidates (entry_id TEXT PRIMARY KEY REFERENCES context_entries(id) ON DELETE CASCADE, document_id TEXT NOT NULL REFERENCES context_documents(id) ON DELETE CASCADE, source_content_hash TEXT NOT NULL, provider TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS context_external_ai_consents (id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN('document','field')), provider_id TEXT NOT NULL, destination_host TEXT NOT NULL, document_id TEXT NOT NULL DEFAULT '', template_id TEXT NOT NULL DEFAULT '', field_key TEXT NOT NULL DEFAULT '', granted_at TEXT NOT NULL, revoked_at TEXT, UNIQUE(scope,provider_id,destination_host,document_id,template_id,field_key)) STRICT;
CREATE INDEX IF NOT EXISTS context_external_ai_consents_active_idx ON context_external_ai_consents(provider_id,destination_host,scope,revoked_at);
CREATE TABLE IF NOT EXISTS experiment_template_requests (id TEXT PRIMARY KEY, source_system TEXT NOT NULL CHECK(source_system IN('metheory')), source_hypothesis_id TEXT, payload_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('pending','template_created','rejected')), template_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(source_system,id)) STRICT;
CREATE INDEX IF NOT EXISTS experiment_template_requests_status_idx ON experiment_template_requests(status,created_at DESC);
